function Merge(intervals: int[][]) -> int[][] {
  let arr: int[][] = [];
  let i = 0;
  while (i < intervals.length()) {
    arr.push(intervals[i]);
    i += 1;
  }
  let a = 1;
  while (a < arr.length()) {
    let key = arr[a];
    let b = a - 1;
    while (b >= 0) {
      if (arr[b][0] <= key[0]) {
        break;
      }
      arr[b + 1] = arr[b];
      b -= 1;
    }
    arr[b + 1] = key;
    a += 1;
  }
  let res: int[][] = [];
  let j = 0;
  while (j < arr.length()) {
    let cur = arr[j];
    if (res.length() == 0) {
      res.push(cur);
    } else {
      let last = res[res.length() - 1];
      if (cur[0] <= last[1]) {
        let newEnd = last[1];
        if (cur[1] > newEnd) {
          newEnd = cur[1];
        }
        res[res.length() - 1] = [last[0], newEnd];
      } else {
        res.push(cur);
      }
    }
    j += 1;
  }
  return res;
}
